"""Compile the existing React UI and copy only runtime assets into Android."""
from pathlib import Path
import shutil, subprocess, tempfile
root = Path(__file__).resolve().parent.parent
assets = root / 'android/app/src/main/assets/web'
with tempfile.TemporaryDirectory(prefix='pin-it-web-') as temporary:
    subprocess.run([str(root/'node_modules/.bin/vite'), 'build', '--outDir', temporary, '--emptyOutDir'], cwd=root, check=True)
    assets.mkdir(parents=True, exist_ok=True)
    # This directory is generated by this helper; never touch application source.
    for child in assets.iterdir():
        if child.is_dir(): shutil.rmtree(child)
        else: child.unlink()
    for child in Path(temporary).iterdir():
        if child.name in {'Pinboard_Notes_Complete.zip', 'Pinboard_Notes_Codebase.pdf'}: continue
        if child.is_dir(): shutil.copytree(child, assets/child.name)
        else: shutil.copy2(child, assets/child.name)
print('Android runtime assets prepared from the original React project')
